import React, { useEffect, useState } from 'react';

function OrdersPage() {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchOrders = async () => {
            const token = localStorage.getItem('token'); // Retrieve token from storage

            try {
                const response = await fetch('/api/orders', {
                    method: 'GET',
                    headers: {
                        Authorization: `Bearer ${token}`, // Include the token
                    },
                });

                if (!response.ok) {
                    const errorData = await response.json();
                    throw new Error(errorData.message || 'Failed to fetch orders.');
                }

                const ordersData = await response.json();
                setOrders(ordersData);
                setLoading(false);
            } catch (error) {
                setError(error.message);
                setLoading(false);
            }
        };

        fetchOrders();
    }, []);

    if (loading) return <p>Loading orders...</p>;
    if (error) return <p className="text-red-500">{error}</p>;

    return (
        <div className="p-8">
            <h1 className="text-2xl font-bold mb-4">Your Orders</h1>
            {orders.length === 0 ? (
                <p>You have no orders yet.</p>
            ) : (
                <ul className="space-y-4">
                    {orders.map((order) => (
                        <li key={order._id} className="border p-4 rounded shadow">
                            <h2 className="text-xl font-bold">Order #{order._id}</h2>
                            <p>Status: {order.status}</p>
                            <p>Total Amount: ${order.totalAmount}</p>
                            <p>Order Date: {new Date(order.createdAt).toLocaleDateString()}</p>
                            <h3 className="text-lg font-bold mt-2">Products:</h3>
                            <ul className="list-disc pl-4">
                                {order.products.map((product, index) => (
                                    <li key={index}>
                                        {product.product.name} - ${product.price} (x{product.quantity})
                                    </li>
                                ))}
                            </ul>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
}

export default OrdersPage;
